#include <everett/profile.h>
#include <iostream>
int main() {
  using B = everett::storage_policy<everett::profile_unit::byte>;
  using I = everett::storage_policy<everett::profile_unit::bit>;
  std::cout << "byte_context," << sizeof(everett::profile_query_context<B>) << '\n'
            << "bit_context," << sizeof(everett::profile_query_context<I>) << '\n'
            << "encoded_record," << sizeof(everett::profile_encoded_record) << '\n'
            << "byte_view," << sizeof(everett::profile_view<B>) << '\n'
            << "bit_view," << sizeof(everett::profile_view<I>) << '\n';
}
